          "set": {
            "ration_seen": true
          }
        }
      ],
      "event_refs": [
        "E03"
      ]
    },
    "kitchen": {
      "title": "다음에는 따뜻한 식사를",
      "screen": "D1-11-kitchen",
      "purpose": "지금은 포장 식량으로 먹지만 수리하면 다른 생활이 가능하다는 작은 기대를 남긴다.",
      "direction": "요리대는 고장 상태. 수리·조리·미니게임을 바로 열지 않는다. 재료를 살폈다면 그때 본 부품과 짧게 연결하고, 못 봤다면 이후 찾을 이유가 된다.",
      "dialogue_intent": "수혁: 요리대를 손봐야 한다는 생각만. 정확한 레시피·고장 원인은 후속 기획.",
      "actions": [
